mapper.select:
select * from aftersale

    and order_id = #{orderId}
    and user_id = #{userId}
    and type = #{type}
    and handler_id = #{handlerId}

order by id desc

select count(*) from aftersale

    and status = #{status}
    and type = #{type}
    and order_id = #{orderId}
    and user_id = #{userId}

select * from aftersale

    and status = #{dto.status}
    and type = #{dto.type}
    and order_id = #{dto.orderId}
    and user_id = #{dto.userId}

order by id desc limit #{begin},#{dto.pageSize}
